func hfParse(b []byte, out *port.Cells) int32 {
	// The integers (decimal, optionally negative, separated by anything else) of a blob, pushed onto `out`.
	var s *port.Src = port.SrcOfBlob(b)
	var n int32 = port.SrcLen(s)
	var i int32 = 0
	var v int32 = 0
	var neg int32 = 0
	var has int32 = 0
	var c int32 = 0
	for i < n {
		c = port.SrcU8(s, i)
		if (c >= 48) && (c <= 57) {
			v = (v * 10) + (c - 48)
			has = 1
		} else {
			if (c == 45) && (has == 0) {
				neg = 1
			}
			if has == 1 {
				if neg == 1 {
					v = 0 - v
				}
				port.CellsPush(out, v)
				v = 0
				has = 0
				neg = 0
			}
			if (c != 45) && (has == 0) {
				neg = 0
			}
		}
		i += 1
	}
	if has == 1 {
		if neg == 1 {
			v = 0 - v
		}
		port.CellsPush(out, v)
	}
	return 0
}

func hfFind(par *port.Cells, x int32) int32 {
	// Union-find root with path halving.
	var a int32 = x
	var p int32 = 0
	var g int32 = 0
	p = port.CellsAt(par, a)
	for p != a {
		g = port.CellsAt(par, p)
		port.CellsSet(par, a, g)
		a = g
		p = port.CellsAt(par, a)
	}
	return a
}

func hfUnion(par *port.Cells, x int32, y int32) int32 {
	var rx int32 = hfFind(par, x)
	var ry int32 = hfFind(par, y)
	if rx < ry {
		port.CellsSet(par, ry, rx)
	}
	if rx > ry {
		port.CellsSet(par, rx, ry)
	}
	return 0
}

func hfLetters(et *port.Cells, ts int32, tl int32, out *port.Cells) int32 {
	// Push the letters and digits of etext[ts, ts + tl) onto `out`, ASCII upper case folded to lower, everything else under 128 dropped.
	var i int32 = 0
	var c int32 = 0
	for i < tl {
		c = port.CellsAt(et, ts+i)
		if (c >= 65) && (c <= 90) {
			c += 32
		}
		if (c >= 128) || (((c >= 97) && (c <= 122)) || ((c >= 48) && (c <= 57))) {
			port.CellsPush(out, c)
		}
		i += 1
	}
	return 0
}

func hfSim(a *port.Cells, b *port.Cells, r0 *port.Cells, r1 *port.Cells) int32 {
	// 1000 - 1000 * lev(a, b) / max(len a, len b); 1000 for two empty ones.
	var la int32 = port.CellsLen(a)
	var lb int32 = port.CellsLen(b)
	var i int32 = 0
	var j int32 = 0
	var x int32 = 0
	var y int32 = 0
	var z int32 = 0
	var cost int32 = 0
	var m int32 = 0
	if (la == 0) && (lb == 0) {
		return 1000
	}
	port.CellsDrop(r0, 0)
	port.CellsDrop(r1, 0)
	j = 0
	for j <= lb {
		port.CellsPush(r0, j)
		port.CellsPush(r1, 0)
		j += 1
	}
	i = 1
	for i <= la {
		port.CellsSet(r1, 0, i)
		j = 1
		for j <= lb {
			cost = 1
			if port.CellsAt(a, i-1) == port.CellsAt(b, j-1) {
				cost = 0
			}
			x = port.CellsAt(r0, j-1) + cost
			y = port.CellsAt(r0, j) + 1
			z = port.CellsAt(r1, j-1) + 1
			if y < x {
				x = y
			}
			if z < x {
				x = z
			}
			port.CellsSet(r1, j, x)
			j += 1
		}
		j = 0
		for j <= lb {
			port.CellsSet(r0, j, port.CellsAt(r1, j))
			j += 1
		}
		i += 1
	}
	m = la
	if lb > m {
		m = lb
	}
	return 1000 - ((1000 * port.CellsAt(r0, lb)) / m)
}

