func TestAShiftedFontIsCaughtByAgreementAlone(emonT *testing.T) {
	var rep *port.Cells = port.NewCells()
	hfDoc(port.TestFile("corpus/synth/pdf/tl-broken-shift.pdf"), port.TestFile("fusion/health/pdf/tl-broken-shift.ocr"), 0, rep)
	port.AssertEq(emonT, port.CellsAt(rep, 0), 5, "tl-broken-shift: five fonts on page 1")
	port.AssertEq(emonT, port.CellsAt(rep, 1), 5, "tl-broken-shift: without OCR every one is trusted (P7.0 cannot tell)")
	hfDoc(port.TestFile("corpus/synth/pdf/tl-broken-shift.pdf"), port.TestFile("fusion/health/pdf/tl-broken-shift.ocr"), 1, rep)
	port.AssertEq(emonT, port.CellsAt(rep, 0), 5, "tl-broken-shift: five fonts")
	port.AssertEq(emonT, port.CellsAt(rep, 1), 4, "tl-broken-shift: with OCR four are trusted")
	port.AssertThat(emonT, port.CellsAt(rep, 2) < 300, "tl-broken-shift: the shifted font is under 300")
	port.AssertEq(emonT, port.CellsAt(rep, 7), 0, "tl-broken-shift: it agrees on nothing")
	port.AssertThat(emonT, port.CellsAt(rep, 5) >= 300, "tl-broken-shift: with groups to count")
}

func TestAnUnmappedFontIsCaughtWithOrWithoutOcr(emonT *testing.T) {
	var rep *port.Cells = port.NewCells()
	hfDoc(port.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), port.TestFile("fusion/health/pdf/tl-broken-unmapped.ocr"), 0, rep)
	port.AssertEq(emonT, port.CellsAt(rep, 1), 4, "tl-broken-unmapped: four of five fonts are trusted without OCR")
	port.AssertEq(emonT, port.CellsAt(rep, 2), 34, "tl-broken-unmapped: the broken one is P7.0's 34")
	hfDoc(port.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), port.TestFile("fusion/health/pdf/tl-broken-unmapped.ocr"), 1, rep)
	port.AssertEq(emonT, port.CellsAt(rep, 1), 4, "tl-broken-unmapped: and with OCR")
	port.AssertEq(emonT, port.CellsAt(rep, 2), 34, "tl-broken-unmapped: still 34: no letters to count")
}

func TestFontsThatLoseGlyphsStayAsTheTextLayerScoredThem(emonT *testing.T) {
	// the Devanagari fonts whose ToUnicode has no matras (P7.0, D240): with OCR in, the same scores; the engine reads none of it
	var rep *port.Cells = port.NewCells()
	hfDoc(port.TestFile("corpus/synth/pdf/script-devanagari.pdf"), port.TestFile("fusion/health/pdf/script-devanagari.ocr"), 1, rep)
	port.AssertEq(emonT, port.CellsAt(rep, 2), 616, "script-devanagari: P7.0's")
	hfDoc(port.TestFile("corpus/synth/pdf/script-mixed.pdf"), port.TestFile("fusion/health/pdf/script-mixed.ocr"), 1, rep)
	port.AssertEq(emonT, port.CellsAt(rep, 2), 201, "script-mixed: P7.0's")
	port.AssertEq(emonT, port.CellsAt(rep, 1), 11, "script-mixed: the same fonts trusted")
}
